package org.rsmod.api.player.events.skillingimport dev.openrune.types.ItemServerTypeimport org.rsmod.api.table.cooking.CookingAlesRowimport org.rsmod.api.table.cooking.CookingFoodsRowimport org.rsmod.api.table.herblore.HerbloreBarbarianMixesRowimport org.rsmod.api.table.herblore.HerbloreCleaningRowimport org.rsmod.api.table.herblore.HerbloreCrushingRowimport org.rsmod.api.table.herblore.HerbloreFinishedRowimport org.rsmod.api.table.herblore.HerbloreSwampTarRowimport org.rsmod.api.table.mining.MiningRocksRowimport org.rsmod.api.table.smithing.SmithingBarsRowimport org.rsmod.api.table.smithing.SmithingCannonBallsRowimport org.rsmod.api.table.smithing.SmithingCrystalSingingRowimport org.rsmod.api.table.smithing.SmithingDragonForgeRowimport org.rsmod.game.loc.BoundLocInfopublic sealed class SkillingProductSource {    public data class Mining(        public val rock: BoundLocInfo,        public val rockData: MiningRocksRow    ) : SkillingProductSource()    public data class Woodcutting(        public val tree: BoundLocInfo,        public val productType: ItemServerType    ) : SkillingProductSource()    public data class Fishing(        public val productType: ItemServerType,    ) : SkillingProductSource()    public data class Cooking(        public val food: CookingFoodsRow,        public val burnt: Boolean,    ) : SkillingProductSource()    /** [mature] is true when the barrel held the rare mature batch. */    public data class Brewing(        public val ale: CookingAlesRow,        public val mature: Boolean,    ) : SkillingProductSource()    public data class HerbCleaning(public val herb: HerbloreCleaningRow) : SkillingProductSource()    public data class HerbCrushing(public val recipe: HerbloreCrushingRow) : SkillingProductSource()    public data class BarbarianMix(public val mix: HerbloreBarbarianMixesRow) :        SkillingProductSource()    /** [extraDose] is true when the amulet of chemistry added a dose. */    public data class FinishedPotion(        public val potion: HerbloreFinishedRow,        public val extraDose: Boolean,    ) : SkillingProductSource()    public data class SwampTar(public val recipe: HerbloreSwampTarRow) : SkillingProductSource()    public data class Anvil(        public val bar: SmithingBarsRow,        public val product: ItemServerType,        public val barCount: Int,    ) : SkillingProductSource()    public data class Smelting(public val bar: SmithingBarsRow) : SkillingProductSource()    public data class CannonballSmelting(public val ball: SmithingCannonBallsRow) :        SkillingProductSource()    public data class DragonForge(public val recipe: SmithingDragonForgeRow) :        SkillingProductSource()    public data class CrystalSinging(public val item: SmithingCrystalSingingRow) :        SkillingProductSource()    public data object GodswordBlade : SkillingProductSource()    public data object GodswordHilt : SkillingProductSource()    public data object GraniteCannonballs : SkillingProductSource()}